{
  "url": "https://github.com/pricing",
  "title": "Pricing · Plans for every developer · GitHub",
  "fields": [
    {
      "name": "Plan Name",
      "type": "TEXT",
      "instruction": "The name of the pricing plan. For example: Free, Team, Enterprise"
    },
    {
      "name": "Price (USD)",
      "type": "NUMBER",
      "instruction": "The price of the plan in USD per month. For example: 0, 4, 21"
    },
    {
      "name": "Billing Period",
      "type": "SINGLE_SELECT",
      "instruction": "The billing period for the plan. Options: per month, per user/month"
    },
    {
      "name": "Plan Description",
      "type": "TEXT",
      "instruction": "A short description of the plan's target audience. For example: The basics for individuals and organizations"
    },
    {
      "name": "Key Features",
      "type": "MULTI_SELECT",
      "instruction": "Select the key features included in the plan. Options: Unlimited public/private repositories, Dependabot security updates, CI/CD minutes, Packages storage, Issues & Projects, Community support, Codespaces, Repository rules, Multiple reviewers, Draft pull requests, Code owners, Required reviewers, Pages and Wikis, Environment deployment branches, Web-based support, Data residency, Enterprise Managed Users, User provisioning, Enterprise Account, Environment protection rules, Audit Log API, SOC reports, FedRAMP, SAML SSO, Advanced auditing, GitHub Connect, Premium support"
    },
    {
      "name": "Plan URL",
      "type": "URL",
      "instruction": "The URL for the plan's sign-up or trial page."
    }
  ],
